SELECT id, coupon_id, customer_id, coupon_no, status, used_order_id, used_at, obtained_at, valid_from, valid_to, version, created_at, updated_at FROM marketing_customer_coupon WHERE deleted = FALSE AND customer_id = #{customerId}
